from collections import defaultdict, deque
import copy

class Graph:

	def __init__(self, graph):
		self.graph = graph
		self.org_graph = [i[:] for i in graph]
		self.ROW = len(graph)
		self.COL = len(graph[0])

	def BFS(self, s, t, parent):
		visited = [False] * self.ROW
		queue = []
		queue.append(s)
		visited[s] = True
		while queue:
			u = queue.pop(0)
			for (ind, val) in enumerate(self.graph[u]):
				if visited[ind] == False and val > 0:
					queue.append(ind)
					visited[ind] = True
					parent[ind] = u
		return True if visited[t] else False

	def dfs(self, graph, s, visited):
		visited[s] = True
		for i in range(len(graph)):
			if graph[s][i] > 0 and (not visited[i]):
				self.dfs(graph, i, visited)

	def minCut(self, source, sink):
		parent = [-1] * self.ROW
		max_flow = 0
		s = -1
		while self.BFS(source, sink, parent):
			path_flow = float('Inf')
			s = sink
			while s != source:
				path_flow = min(path_flow, self.graph[parent[s]][s])
				s = parent[s]
			max_flow += path_flow
			v = sink
			while v != source:
				u = parent[v]
				self.graph[u][v] -= path_flow
				self.graph[v][u] += path_flow
				v = parent[v]
		if s != -1:
			visited = len(self.graph) * [False]
			self.dfs(self.graph, s, visited)
			cut_list = []
			for i in range(self.ROW):
				for j in range(self.COL):
					if self.graph[i][j] == 0 and self.org_graph[i][j] > 0 and visited[i]:
						cut_list.append(str(i) + ' ' + str(j))
			return cut_list
		return []

class Solution:

	def build_directed_graph(self, Graph):
		Directed_Graph = {}
		mapping_data = {}
		for node in Graph.keys():
			mapping_data[str(node)] = node
			if 'forward' + str(node) not in Directed_Graph.keys():
				Directed_Graph['forward' + str(node)] = defaultdict(int)
			Directed_Graph['forward' + str(node)]['backwar' + str(node)] += 1
		for source in Graph.keys():
			for target in Graph[source]:
				mapping_data[str(source)] = source
				mapping_data[str(target)] = target
				if 'backwar' + str(source) not in Directed_Graph.keys():
					Directed_Graph['backwar' + str(source)] = defaultdict(int)
				Directed_Graph['backwar' + str(source)]['forward' + str(target)] += 1
		return (Directed_Graph, mapping_data)

	def BFS(self, graph, s, t, parent):
		visited = defaultdict(int)
		queue = deque()
		queue.append(s)
		visited[s] = True
		while bool(queue):
			popped_vertex = queue.popleft()
			if graph.get(popped_vertex, 0):
				for vertex in graph[popped_vertex].keys():
					val = graph[popped_vertex][vertex]
					if visited[vertex] == False and val > 0:
						queue.append(vertex)
						visited[vertex] = True
						parent[vertex] = popped_vertex
		return True if visited[t] else False

	def dfs(self, graph, s, visited):
		visited[s] = True
		for i in range(len(graph)):
			if graph[s][i] > 0 and (not visited[i]):
				self.dfs(graph, i, visited)

	def minCut(self, graph, source, sink):
		parent = defaultdict(int)
		s = -1
		max_flow = 0
		edge_cut = []
		new_graph = {}
		for i in graph.keys():
			new_graph[i] = defaultdict(int)
			for j in graph[i].keys():
				new_graph[i][j] = graph[i][j]
		while self.BFS(new_graph, source, sink, parent):
			path_flow = float('Inf')
			s = sink
			while s != source:
				path_flow = min(path_flow, new_graph[parent[s]][s])
				s = parent[s]
			max_flow += path_flow
			v = sink
			while v != source:
				u = parent[v]
				new_graph[u][v] -= path_flow
				new_graph[v][u] += path_flow
				v = parent[v]
		if s != -1:
			visited = defaultdict(int)
			self.dfs(new_graph, s, visited)
			for i in sorted(graph.keys()):
				for j in sorted(graph[i].keys()):
					if visited[i] and (not visited[j]) and graph[i][j]:
						edge_cut.append(str(i) + ' ' + str(j))
		return edge_cut

